<?php require_once 'includes.php';require_login();$user=current_user();if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['request_id'],$_POST['decision'])){verify_csrf();$rid=filter_var($_POST['request_id'],FILTER_VALIDATE_INT);$decision=(string)$_POST['decision'];if($rid&&in_array($decision,['accepted','declined'],true)){try{db()->beginTransaction();$s=db()->prepare('SELECT r.*,t.host_id,t.seats_available FROM trip_requests r JOIN trips t ON t.id=r.trip_id WHERE r.id=? FOR UPDATE');$s->execute([$rid]);$r=$s->fetch();if(!$r||(int)$r['host_id']!==(int)$_SESSION['user_id'])throw new RuntimeException('Request not found.');if($r['status']!=='pending')throw new RuntimeException('Request already handled.');if($decision==='accepted'){if((int)$r['seats_requested']>(int)$r['seats_available'])throw new RuntimeException('Not enough seats remain.');db()->prepare('UPDATE trips SET seats_available=seats_available-? WHERE id=?')->execute([$r['seats_requested'],$r['trip_id']]);}db()->prepare('UPDATE trip_requests SET status=? WHERE id=?')->execute([$decision,$rid]);db()->commit();$_SESSION['flash']='Request updated.';}catch(Throwable $x){if(db()->inTransaction())db()->rollBack();$_SESSION['flash']=$x->getMessage();}}header('Location: profile.php');exit;}$s=db()->prepare('SELECT * FROM trips WHERE host_id=? ORDER BY created_at DESC');$s->execute([$_SESSION['user_id']]);$mine=$s->fetchAll();$s=db()->prepare('SELECT r.*,t.title,t.from_city,t.to_place,t.travel_date,u.name requester_name FROM trip_requests r JOIN trips t ON t.id=r.trip_id JOIN users u ON u.id=r.requester_id WHERE t.host_id=? ORDER BY r.created_at DESC');$s->execute([$_SESSION['user_id']]);$requests=$s->fetchAll();$s=db()->prepare('SELECT r.*,t.title,t.from_city,t.to_place,t.travel_date,u.name host_name FROM trip_requests r JOIN trips t ON t.id=r.trip_id JOIN users u ON u.id=t.host_id WHERE r.requester_id=? ORDER BY r.created_at DESC');$s->execute([$_SESSION['user_id']]);$sent=$s->fetchAll();page_header('Your profile');?><section class="page-intro"><p class="eyebrow">YOUR TRAVEL SPACE</p><h1>Hello, <?=e($user['name']??'traveller')?>.</h1><p>Manage trip listings and requests to join journeys.</p></section><div class="page-wrap"><div class="panel"><h2><?=e($user['name']??'Traveller')?></h2><p><?=e($user['email']??'')?></p><a class="btn btn-primary" href="create-trip.php">Create a trip</a></div><section class="panel" style="margin-top:20px"><h2>Your listings</h2><?php if(!$mine):?><p>No trips published yet.</p><?php else:?><div class="trip-list"><?php foreach($mine as $t):?><article class="trip-card"><div><h3><?=e($t['title'])?></h3><p class="trip-meta"><?=e($t['from_city'])?> → <?=e($t['to_place'])?> · <?=e(date('d M Y',strtotime($t['travel_date'])))?> · <?=e($t['status'])?></p></div><a class="btn btn-light" href="trip.php?id=<?=(int)$t['id']?>">View</a></article><?php endforeach;?></div><?php endif;?></section><section class="panel" style="margin-top:20px"><h2>Requests for your trips</h2><?php if(!$requests):?><p>No requests yet.</p><?php else:?><div class="trip-list"><?php foreach($requests as $r):?><article class="trip-card"><div><h3><?=e($r['title'])?></h3><p><?=e($r['requester_name'])?> requested <?= (int)$r['seats_requested']?> seat(s) · <?=e($r['status'])?></p><p><?=e($r['from_city'])?> → <?=e($r['to_place'])?> · <?=e(date('d M Y',strtotime($r['travel_date'])))?></p><?php if($r['message']):?><p><?=e($r['message'])?></p><?php endif;?></div><?php if($r['status']==='pending'):?><form method="post" class="inline-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="request_id" value="<?=(int)$r['id']?>"><button class="btn btn-primary" name="decision" value="accepted">Accept</button><button class="btn btn-light" name="decision" value="declined">Decline</button></form><?php endif;?></article><?php endforeach;?></div><?php endif;?></section><section class="panel" style="margin-top:20px"><h2>Your join requests</h2><?php if(!$sent):?><p>You have not requested to join trips yet.</p><?php else:?><div class="trip-list"><?php foreach($sent as $r):?><article class="trip-card"><div><h3><?=e($r['title'])?></h3><p><?=e($r['from_city'])?> → <?=e($r['to_place'])?> · Host <?=e($r['host_name'])?></p></div><span class="pill"><?=e($r['status'])?></span></article><?php endforeach;?></div><?php endif;?></section></div><?php page_footer();?>